// Deduplicate against the breach history stored in Google Sheets.
// A breach is treated as new when the Name is unseen, or when HIBP has
// changed its ModifiedDate/AddedDate since the last stored run.

const cfg = $('Set Workflow Variables').first().json;
const latest = $('Fetch Latest Breach from Have I Been Pwned API').first().json;

if (!latest || !latest.Name) {
  return [];
}

const rows = $('Read Breach History from Google Sheet')
  .all()
  .map(i => i.json)
  .filter(r => r && r.Name);

const stamp = b => String(b.ModifiedDate || b.AddedDate || '');

const existing = rows.find(r => r.Name === latest.Name && stamp(r) === stamp(latest));

// Already recorded with the same timestamp -> exit quietly.
if (existing && cfg.reprocessKnownBreaches !== true) {
  return [];
}

const previouslySeen = rows.some(r => r.Name === latest.Name);

return [
  {
    json: {
      ...latest,
      isUpdate: previouslySeen
    }
  }
];

// Turn the raw HIBP record into a scored, alertable event.
// Edit the weights below to match your own risk appetite.

const cfg = $('Set Workflow Variables').first().json;
const b = $input.first().json;

const toList = v => String(v || '')
  .split(',')
  .map(s => s.trim().toLowerCase())
  .filter(Boolean);

const watchDomains = toList(cfg.watchlistDomains);
const watchKeywords = toList(cfg.watchlistKeywords);

const dataClasses = Array.isArray(b.DataClasses)
  ? b.DataClasses
  : (b.DataClasses ? [b.DataClasses] : []);
const dcLower = dataClasses.map(d => String(d).toLowerCase());
const has = needle => dcLower.some(d => d.includes(needle));

let score = 0;
const reasons = [];

// --- Blast radius ---
const pwn = Number(b.PwnCount || 0);
if (pwn >= 10000000) { score += 3; reasons.push('Over 10M records exposed'); }
else if (pwn >= 1000000) { score += 2; reasons.push('Over 1M records exposed'); }
else if (pwn >= 100000) { score += 1; reasons.push('Over 100K records exposed'); }

// --- Data sensitivity ---
if (has('password')) { score += 3; reasons.push('Credentials exposed'); }
if (has('credit card') || has('bank account')) { score += 3; reasons.push('Financial data exposed'); }
if (has('social security') || has('government issued id') || has('passport')) { score += 2; reasons.push('Government identifiers exposed'); }
if (has('security question')) { score += 1; reasons.push('Security questions exposed'); }
if (has('health')) { score += 2; reasons.push('Health data exposed'); }

// --- HIBP flags ---
if (b.IsSensitive === true) { score += 2; reasons.push('Flagged sensitive by HIBP'); }
if (b.IsMalware === true) { score += 1; reasons.push('Sourced from malware/stealer logs'); }
if (b.IsVerified === false) { score -= 1; reasons.push('Unverified breach'); }

// --- Your watchlist ---
const haystack = [b.Name, b.Title, b.Domain, b.Description].join(' ').toLowerCase();
const domainHit = watchDomains.some(d => haystack.includes(d));
const keywordHit = watchKeywords.some(k => haystack.includes(k));
const watchlistHit = domainHit || keywordHit;
if (watchlistHit) { score += 3; reasons.push('Matches your watchlist'); }

let severity = 'LOW';
if (score >= 8) severity = 'CRITICAL';
else if (score >= 5) severity = 'HIGH';
else if (score >= 3) severity = 'MEDIUM';

const rank = { LOW: 0, MEDIUM: 1, HIGH: 2, CRITICAL: 3 };
const floor = String(cfg.minimumSeverity || 'LOW').toUpperCase();

let shouldAlert = rank[severity] >= (rank[floor] ?? 0);
if (watchlistHit && cfg.alwaysAlertOnWatchlist === true) {
  shouldAlert = true;
}

return [
  {
    json: {
      ...b,
      DataClassesText: dataClasses.join(', '),
      SeverityScore: score,
      Severity: severity,
      WatchlistHit: watchlistHit,
      ScoreReasons: reasons.join('; '),
      CheckedAt: new Date().toISOString(),
      shouldAlert
    }
  }
];

// Builds the HTML alert email.
// Table-based layout with inline styles so it renders in Gmail, Outlook,
// Apple Mail and mobile clients. Edit colours in the palette below.

const cfg = $('Set Workflow Variables').first().json;
const b = $('Score Breach Severity').first().json;

const palette = {
  CRITICAL: { bar: '#b91c1c', soft: '#fef2f2', ink: '#7f1d1d' },
  HIGH:     { bar: '#c2410c', soft: '#fff7ed', ink: '#7c2d12' },
  MEDIUM:   { bar: '#a16207', soft: '#fefce8', ink: '#713f12' },
  LOW:      { bar: '#475569', soft: '#f8fafc', ink: '#334155' }
};
const severity = String(b.Severity || 'LOW').toUpperCase();
const c = palette[severity] || palette.LOW;

const fmtDate = v => v ? new Date(v).toLocaleString('en-US', { dateStyle: 'medium', timeStyle: 'short' }) : 'Not recorded';
const fmtNum = v => v ? Number(v).toLocaleString('en-US') : 'Not recorded';

const dataClasses = Array.isArray(b.DataClasses)
  ? b.DataClasses
  : String(b.DataClassesText || '').split(',').map(s => s.trim()).filter(Boolean);

const HIGH_RISK = ['password', 'credit card', 'bank account', 'social security',
  'government issued id', 'passport', 'health', 'security question'];
const isHot = d => HIGH_RISK.some(k => String(d).toLowerCase().includes(k));

const reasons = String(b.ScoreReasons || '')
  .split(';')
  .map(s => s.trim())
  .filter(Boolean);

const floor = String(cfg.minimumSeverity || 'LOW').toUpperCase();
const watchlistDriven = b.WatchlistHit === true && cfg.alwaysAlertOnWatchlist === true;

// --- Why you are getting this email ---
const whyLines = [];
if (watchlistDriven) {
  whyLines.push('This breach matched an entry on <strong>your watchlist</strong>, so it is sent regardless of score.');
} else {
  whyLines.push(`This breach scored <strong>${b.SeverityScore}</strong> and rated <strong>${severity}</strong>, which meets or exceeds your minimum alert level of <strong>${floor}</strong>.`);
}
if (b.isUpdate) {
  whyLines.push('Have I Been Pwned has <strong>revised a breach record you already had on file</strong>. The details below may have changed since you last saw them.');
}
whyLines.push('A scheduled workflow checks the Have I Been Pwned feed once a day. Breaches below your threshold are still logged to your spreadsheet, they just do not trigger an email.');

// --- Reusable style fragments ---
const FONT = "font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Arial,sans-serif";
const labelCell = `${FONT};font-size:13px;color:#64748b;padding:9px 12px 9px 0;width:150px;vertical-align:top;border-bottom:1px solid #f1f5f9;`;
const valueCell = `${FONT};font-size:14px;color:#0f172a;padding:9px 0;vertical-align:top;border-bottom:1px solid #f1f5f9;`;
const h2 = `${FONT};font-size:12px;font-weight:700;letter-spacing:1.1px;text-transform:uppercase;color:#94a3b8;margin:0 0 12px 0;`;

const row = (label, value) =>
  `<tr><td style="${labelCell}">${label}</td><td style="${valueCell}">${value}</td></tr>`;

const chip = d => {
  const hot = isHot(d);
  const bg = hot ? '#fef2f2' : '#f1f5f9';
  const fg = hot ? '#b91c1c' : '#475569';
  const bd = hot ? '#fecaca' : '#e2e8f0';
  return `<span style="display:inline-block;background:${bg};color:${fg};border:1px solid ${bd};border-radius:4px;padding:4px 10px;margin:0 6px 6px 0;${FONT};font-size:13px;">${d}</span>`;
};

const preheader = `${severity} severity, risk score ${b.SeverityScore}. ${fmtNum(b.PwnCount)} accounts exposed at ${b.Domain || b.Name}.`;
const hibpUrl = `https://haveibeenpwned.com/PwnedWebsites#${encodeURIComponent(b.Name || '')}`;

const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>${b.Title || b.Name} breach alert</title>
</head>
<body style="margin:0;padding:0;background-color:#eef1f5;">

<div style="display:none;max-height:0;overflow:hidden;opacity:0;">${preheader}</div>

<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color:#eef1f5;">
<tr><td align="center" style="padding:28px 12px;">

<table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" style="width:100%;max-width:600px;background:#ffffff;border:1px solid #e2e8f0;border-radius:12px;overflow:hidden;">

  <!-- Severity bar -->
  <tr>
    <td bgcolor="${c.bar}" style="background:${c.bar};padding:13px 26px;">
      <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">
        <tr>
          <td style="${FONT};font-size:12px;font-weight:700;letter-spacing:1.2px;color:#ffffff;">
            ${severity} &nbsp;&middot;&nbsp; RISK SCORE ${b.SeverityScore}
          </td>
          <td align="right" style="${FONT};font-size:12px;color:#ffffff;opacity:.85;">
            BREACH ALERT
          </td>
        </tr>
      </table>
    </td>
  </tr>

  <!-- Title -->
  <tr>
    <td style="padding:26px 26px 18px 26px;">
      <table role="presentation" cellpadding="0" cellspacing="0" border="0">
        <tr>
          ${b.LogoPath ? `<td width="56" style="padding-right:16px;vertical-align:middle;"><img src="${b.LogoPath}" width="56" alt="" style="display:block;width:56px;height:auto;border-radius:8px;"></td>` : ''}
          <td style="vertical-align:middle;">
            <div style="${FONT};font-size:22px;font-weight:700;color:#0f172a;line-height:1.25;">${b.Title || b.Name}</div>
            <div style="${FONT};font-size:14px;color:#64748b;padding-top:4px;">${b.Domain || 'Domain not recorded'}</div>
          </td>
        </tr>
      </table>
      <div style="padding-top:14px;">
        ${b.WatchlistHit ? '<span style="display:inline-block;background:#f5f3ff;color:#6d28d9;border:1px solid #ddd6fe;border-radius:4px;padding:4px 10px;margin:0 6px 6px 0;' + FONT + ';font-size:12px;font-weight:600;">ON YOUR WATCHLIST</span>' : ''}
        ${b.isUpdate ? '<span style="display:inline-block;background:#eff6ff;color:#1d4ed8;border:1px solid #bfdbfe;border-radius:4px;padding:4px 10px;margin:0 6px 6px 0;' + FONT + ';font-size:12px;font-weight:600;">UPDATED RECORD</span>' : ''}
        ${b.IsVerified === false ? '<span style="display:inline-block;background:#f8fafc;color:#64748b;border:1px solid #e2e8f0;border-radius:4px;padding:4px 10px;margin:0 6px 6px 0;' + FONT + ';font-size:12px;font-weight:600;">UNVERIFIED</span>' : ''}
      </div>
    </td>
  </tr>

  <!-- Why you are getting this -->
  <tr>
    <td style="padding:0 26px 22px 26px;">
      <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:${c.soft};border-left:3px solid ${c.bar};border-radius:0 8px 8px 0;">
        <tr><td style="padding:16px 18px;">
          <div style="${FONT};font-size:13px;font-weight:700;color:${c.ink};padding-bottom:8px;">Why you are getting this email</div>
          ${whyLines.map(l => `<div style="${FONT};font-size:13px;line-height:1.65;color:#334155;padding-bottom:6px;">${l}</div>`).join('')}
        </td></tr>
      </table>
    </td>
  </tr>

  <!-- Scoring breakdown -->
  ${reasons.length ? `
  <tr>
    <td style="padding:0 26px 22px 26px;">
      <div style="${h2}">How this score was reached</div>
      <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">
        ${reasons.map(r => `<tr><td width="16" style="${FONT};font-size:13px;color:${c.bar};padding:3px 8px 3px 0;vertical-align:top;">&bull;</td><td style="${FONT};font-size:13px;line-height:1.6;color:#334155;padding:3px 0;">${r}</td></tr>`).join('')}
      </table>
    </td>
  </tr>` : ''}

  <!-- Breach details -->
  <tr>
    <td style="padding:0 26px 22px 26px;">
      <div style="${h2}">Breach details</div>
      <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">
        ${row('Accounts exposed', `<strong>${fmtNum(b.PwnCount)}</strong>`)}
        ${row('Date of breach', b.BreachDate || 'Not recorded')}
        ${row('Added to HIBP', fmtDate(b.AddedDate))}
        ${row('Last modified', fmtDate(b.ModifiedDate))}
        ${row('Verified by HIBP', b.IsVerified ? 'Yes' : 'No')}
        ${row('Flagged sensitive', b.IsSensitive ? 'Yes' : 'No')}
      </table>
    </td>
  </tr>

  <!-- Data compromised -->
  <tr>
    <td style="padding:0 26px 22px 26px;">
      <div style="${h2}">Data compromised</div>
      ${dataClasses.length ? dataClasses.map(chip).join('') : `<span style="${FONT};font-size:13px;color:#64748b;">Not specified by the source.</span>`}
      ${dataClasses.some(isHot) ? `<div style="${FONT};font-size:12px;color:#b91c1c;padding-top:8px;">Highlighted types carry elevated risk and contributed to the score.</div>` : ''}
    </td>
  </tr>

  <!-- Description -->
  ${b.Description ? `
  <tr>
    <td style="padding:0 26px 22px 26px;">
      <div style="${h2}">What happened</div>
      <div style="${FONT};font-size:14px;line-height:1.7;color:#334155;">${b.Description}</div>
    </td>
  </tr>` : ''}

  <!-- CTA -->
  <tr>
    <td style="padding:0 26px 26px 26px;">
      <table role="presentation" cellpadding="0" cellspacing="0" border="0">
        <tr><td bgcolor="${c.bar}" style="background:${c.bar};border-radius:6px;">
          <a href="${hibpUrl}" style="display:inline-block;padding:11px 22px;${FONT};font-size:14px;font-weight:600;color:#ffffff;text-decoration:none;">View on Have I Been Pwned</a>
        </td></tr>
      </table>
    </td>
  </tr>

  <!-- Suggested next steps -->
  <tr>
    <td style="padding:0 26px 26px 26px;">
      <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;">
        <tr><td style="padding:16px 18px;">
          <div style="${FONT};font-size:13px;font-weight:700;color:#0f172a;padding-bottom:8px;">Suggested next steps</div>
          <div style="${FONT};font-size:13px;line-height:1.7;color:#475569;">
            1. Check whether anyone in your organisation holds an account with this service.<br>
            2. If credentials were exposed, force a reset and look for password reuse elsewhere.<br>
            3. Expect phishing that references this breach, and warn affected users before attackers do.
          </div>
        </td></tr>
      </table>
    </td>
  </tr>

</table>

<!-- Footer -->
<table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" style="width:100%;max-width:600px;">
  <tr><td style="padding:18px 26px;${FONT};font-size:11px;line-height:1.7;color:#94a3b8;">
    Source: Have I Been Pwned <span style="color:#64748b;">latestbreach</span> feed. Checked ${fmtDate(b.CheckedAt)}.<br>
    Current alert threshold: <strong style="color:#64748b;">${floor}</strong>. To change what reaches your inbox, edit the Set Workflow Variables node in this workflow.
  </td></tr>
</table>

</td></tr>
</table>
</body>
</html>`;

return [{ json: { html } }];

// Builds the Slack chat.postMessage payload for the scored breach.
// Blocks are wrapped in an attachment so Slack draws the coloured bar down
// the left edge, which is what turns the message into a severity-coded card.

const cfg = $('Set Workflow Variables').first().json;
const b = $('Score Breach Severity').first().json;

const severity = String(b.Severity || 'LOW').toUpperCase();

const THEME = {
  CRITICAL: { colour: '#b91c1c', dot: ':red_circle:' },
  HIGH:     { colour: '#c2410c', dot: ':large_orange_circle:' },
  MEDIUM:   { colour: '#a16207', dot: ':large_yellow_circle:' },
  LOW:      { colour: '#64748b', dot: ':white_circle:' }
};
const t = THEME[severity] || THEME.LOW;

const fmtNum = v => (v || v === 0) ? Number(v).toLocaleString('en-US') : 'Not recorded';
const trunc = (s, n) => String(s).length > n ? String(s).slice(0, n - 1).trimEnd() + '\u2026' : String(s);

// HIBP descriptions are HTML. Anchors become sentinels first, otherwise the
// tag stripper below would eat the <url|label> syntax it had just created.
const toMrkdwn = html => String(html || '')
  .replace(/<a[^>]*href="([^"]+)"[^>]*>(.*?)<\/a>/gi, '\u0001$1|$2\u0002')
  .replace(/<[^>]+>/g, '')
  .replace(/\u0001/g, '<')
  .replace(/\u0002/g, '>')
  .replace(/&quot;/g, '"')
  .replace(/&#x27;/g, "'")
  .replace(/&amp;/g, '&')
  .replace(/\s+/g, ' ')
  .trim();

const dataClasses = Array.isArray(b.DataClasses)
  ? b.DataClasses
  : String(b.DataClassesText || '').split(',').map(s => s.trim()).filter(Boolean);

const HIGH_RISK = ['password', 'credit card', 'bank account', 'social security',
  'government issued id', 'passport', 'health', 'security question'];
const isHot = d => HIGH_RISK.some(k => String(d).toLowerCase().includes(k));

const reasons = String(b.ScoreReasons || '')
  .split(';')
  .map(s => s.trim())
  .filter(Boolean);

const floor = String(cfg.minimumSeverity || 'LOW').toUpperCase();
const watchlistDriven = b.WatchlistHit === true && cfg.alwaysAlertOnWatchlist === true;

// Visual score meter. SCORE_CAP is display only, it does not affect the bands.
const SCORE_CAP = 10;
const score = Number(b.SeverityScore) || 0;
const filled = Math.max(0, Math.min(SCORE_CAP, score));
const meter = '\u25B0'.repeat(filled) + '\u25B1'.repeat(SCORE_CAP - filled);

// Link straight to the breach log so responders can open the history.
const sheetId = cfg.sheetId;
const sheetUrl = (sheetId && sheetId !== 'PASTE_YOUR_GOOGLE_SHEET_ID_HERE')
  ? `https://docs.google.com/spreadsheets/d/${sheetId}/edit`
  : '';

const hibpUrl = `https://haveibeenpwned.com/PwnedWebsites#${encodeURIComponent(b.Name || '')}`;

const blocks = [];

// --- Header ---
blocks.push({
  type: 'header',
  text: { type: 'plain_text', text: trunc(`${severity}: ${b.Title || b.Name}`, 148), emoji: true }
});

// --- Score meter + status tags ---
const tags = [`${t.dot} *${severity}*`, `${meter}  ${score}`];
if (b.WatchlistHit) tags.push(':eyes: watchlist');
if (b.isUpdate) tags.push(':arrows_counterclockwise: updated');
if (b.IsVerified === false) tags.push(':grey_question: unverified');
if (b.IsSensitive === true) tags.push(':lock: sensitive');

blocks.push({
  type: 'context',
  elements: [{ type: 'mrkdwn', text: tags.join('   \u00b7   ') }]
});

// --- Identity line, with the breach logo as a thumbnail ---
const identity = {
  type: 'section',
  text: {
    type: 'mrkdwn',
    text: `*${b.Domain || 'Domain not recorded'}*\n${fmtNum(b.PwnCount)} accounts exposed  \u00b7  breached ${b.BreachDate || 'date not recorded'}`
  }
};
if (b.LogoPath) {
  identity.accessory = {
    type: 'image',
    image_url: b.LogoPath,
    alt_text: `${b.Name} logo`
  };
}
blocks.push(identity);

// --- Why this fired ---
const why = watchlistDriven
  ? `Matched *your watchlist*, so it posts regardless of score.`
  : `Scored *${score}* (${severity}), at or above your *${floor}* threshold.`;

blocks.push({
  type: 'section',
  text: { type: 'mrkdwn', text: `*Why this fired*\n${why}` }
});

// --- Scoring breakdown ---
if (reasons.length) {
  blocks.push({
    type: 'section',
    text: { type: 'mrkdwn', text: trunc(`*How the score was reached*\n${reasons.map(r => `\u2022 ${r}`).join('\n')}`, 2900) }
  });
}

// --- Data compromised, high-risk types bolded ---
if (dataClasses.length) {
  const rendered = dataClasses
    .map(d => isHot(d) ? `*${d}*` : d)
    .join('  \u00b7  ');
  const note = dataClasses.some(isHot) ? '\n_Bold types carry elevated risk and drove the score._' : '';
  blocks.push({
    type: 'section',
    text: { type: 'mrkdwn', text: trunc(`*Data compromised*\n${rendered}${note}`, 2900) }
  });
}

// --- What happened ---
const desc = toMrkdwn(b.Description);
if (desc) {
  blocks.push({
    type: 'section',
    text: { type: 'mrkdwn', text: trunc(`*What happened*\n${desc}`, 1200) }
  });
}

blocks.push({ type: 'divider' });

// --- Actions ---
const elements = [{
  type: 'button',
  text: { type: 'plain_text', text: 'View on Have I Been Pwned', emoji: true },
  url: hibpUrl,
  action_id: 'view_hibp'
}];
if (severity === 'CRITICAL' || severity === 'HIGH') {
  elements[0].style = 'danger';
}
if (sheetUrl) {
  elements.push({
    type: 'button',
    text: { type: 'plain_text', text: 'Open breach log', emoji: true },
    url: sheetUrl,
    action_id: 'open_log'
  });
}
blocks.push({ type: 'actions', elements });

// --- Footer ---
const checked = b.CheckedAt
  ? String(b.CheckedAt).replace('T', ' ').slice(0, 16) + ' UTC'
  : 'just now';

blocks.push({
  type: 'context',
  elements: [{
    type: 'mrkdwn',
    text: `Have I Been Pwned \`latestbreach\` feed  \u00b7  checked ${checked}  \u00b7  alert threshold *${floor}*`
  }]
});

const fallbackText = `[${severity}] ${b.Title || b.Name} | ${fmtNum(b.PwnCount)} accounts exposed`;

// chat.postMessage body. The attachment wrapper draws the coloured bar.
// Unfurling is off so links in the description do not add preview cards.
const payload = {
  channel: cfg.slackChannel,
  text: fallbackText,
  unfurl_links: false,
  unfurl_media: false,
  attachments: [
    {
      color: t.colour,
      fallback: fallbackText,
      blocks
    }
  ]
};

return [{
  json: {
    slackPayload: JSON.stringify(payload),
    fallbackText,
    severity
  }
}];
